import os

def detect_objects(image_path, labels, threshold=None, model_size="tiny", padding=20):
    detect_object = os.listdir(image_path)
    for object in detect_object:
        for label in labels:
            if label == object:
                if float(threshold) > 0.35 and float(threshold) < 1.0:
                    image_path = image_path + '/' + object
                    if model_size == "base":
                        model_path = 'assets/classification_models/base/model_' + model_size + '.bin'
                    else:
                        model_path = 'assets/classification_models/tiny/model_' + model_size + '.bin'
                    with open(model_path, 'rb') as model_file:
                        model = pickle.load(model_file)
                    with open(image_path, 'rb') as image_file:
                        model_image = pickle.load(image_file)
                    model_label = model.predict(model_image)[0][0][0]
                    if model_label == int(object):
                        print(f"{object} detected in {image_path}")
                        break
                else:
                    print(f"Object {object} is not detected in the image.")
    return

